  static String? getPsalmAmharic(int chapter) {
    return _psalmsAm[chapter];
  }

  static String? getPsalmByLanguage(String languageCode, int chapter) {
    final lang = languageCode.toLowerCase();
    if (lang == 'am' || lang.startsWith('am')) {
      return _psalmsAm[chapter] ?? _psalms[chapter];
    }
    return _psalms[chapter];
  }
